SET NAMES utf8mb4;

-- ----------------------------
-- 1. 章节表
-- ----------------------------
DROP TABLE IF EXISTS `qh_chapter`;
CREATE TABLE `qh_chapter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '章节编号',
  `num` int NOT NULL COMMENT '章序号',
  `title` varchar(128) NOT NULL COMMENT '章节标题',
  `cover` int NOT NULL DEFAULT 0 COMMENT '封面图序号',
  `summary` varchar(1024) NOT NULL DEFAULT '' COMMENT '章节摘要',
  `content` text COMMENT '章节正文',
  `item_count` int NOT NULL DEFAULT 0 COMMENT '建议条数',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_chapter_num`(`num` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '循证健康指南-章节表';

-- ----------------------------
-- 2. 建议条目表
-- ----------------------------
DROP TABLE IF EXISTS `qh_chapter_item`;
CREATE TABLE `qh_chapter_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '条目编号',
  `chapter_id` bigint NOT NULL COMMENT '所属章节ID',
  `sort_no` int NOT NULL DEFAULT 0 COMMENT '排序号',
  `title` varchar(255) NOT NULL COMMENT '建议标题',
  `detail` varchar(512) NOT NULL DEFAULT '' COMMENT '建议说明',
  `level` varchar(4) NOT NULL DEFAULT '' COMMENT '证据等级 A/B/C',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_item_chapter`(`chapter_id` ASC, `sort_no` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '循证健康指南-建议条目表';

-- ----------------------------
-- 3. 用户标记进度表（替代原来的内存 DATA.kbMarks）
-- ----------------------------
DROP TABLE IF EXISTS `qh_chapter_mark`;
CREATE TABLE `qh_chapter_mark`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '标记编号',
  `chapter_id` bigint NOT NULL COMMENT '章节ID',
  `item_index` int NOT NULL COMMENT '条目序号(从0开始，对应前端索引)',
  `mark_state` tinyint NOT NULL DEFAULT 0 COMMENT '状态 0未标记 1待做 2已做到',
  `student_id` bigint NOT NULL DEFAULT 1 COMMENT '学生ID',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_mark`(`chapter_id`, `item_index`, `student_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '循证健康指南-用户标记进度表';

