INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(1, 1, '不要早死', 1, '这一节讲三件事：车祸、火灾、中毒这类意外和伤害死亡；少数几种证据最硬的疫苗和筛查；身体出了什么信号就该去查一查。收益那一栏的数字，来自随机分组的试验、跟踪一大批人很多年的研究，或者官方统计。成本那一栏是作者按市面价格的粗略估计，只用来互相比较，不要拿去引用。', '这一节讲三件事：车祸、火灾、中毒这类意外和伤害死亡；少数几种证据最硬的疫苗和筛查；身体出了什么信号就该去查一查。收益那一栏的数字，来自随机分组的试验、跟踪一大批人很多年的研究，或者官方统计。成本那一栏是作者按市面价格的粗略估计，只用来互相比较，不要拿去引用。', 43, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(2, 2, '不要慢慢死', 2, '本节只收两类慢性风险：一类对总死亡率影响大，一类证据硬。条目按性价比从高到低排。有几条标了「随机试验」，意思是把人随机分成两组来比，这种结果最可信。其余数字都来自只跟踪记录、不做分组的研究。这类研究算出的 HR、RR 等风险比里混着两种干扰：这些人本来就不一样，有人是先病了才这么做。所以这些数字只说明方向和大概多大，不代表照做就能降这么多。', '本节只收两类慢性风险：一类对总死亡率影响大，一类证据硬。条目按性价比从高到低排。有几条标了「随机试验」，意思是把人随机分成两组来比，这种结果最可信。其余数字都来自只跟踪记录、不做分组的研究。这类研究算出的 HR、RR 等风险比里混着两种干扰：这些人本来就不一样，有人是先病了才这么做。所以这些数字只说明方向和大概多大，不代表照做就能降这么多。', 43, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(3, 3, '不要浪费精力', 3, '本节只算精力和时间账。看的是四样东西：你每天能用的注意力、反应快不快、出错多不多、被打断以后要多久才回得来。所有数字都是直接测出来的，来自实验，或者来自跟踪一群人做的记录（队列研究）。这些数字不换算成寿命，也不换算成死亡率。本节多数条目的证据等级是 B。这个领域本来就这样，不代表建议不成立。第 19 条讲的是和警察、医生、柜员打交道时该有的预期，引的是法规，不是实验，所以等级记 C。第 15 条（把悲观念头当症状看）和第 22 条（把「别人要求我完美」当症状看）引的是死亡率与自杀风险的数字，口径和本节其他条目不一样，不放在一起比较。', '本节只算精力和时间账。看的是四样东西：你每天能用的注意力、反应快不快、出错多不多、被打断以后要多久才回得来。所有数字都是直接测出来的，来自实验，或者来自跟踪一群人做的记录（队列研究）。这些数字不换算成寿命，也不换算成死亡率。本节多数条目的证据等级是 B。这个领域本来就这样，不代表建议不成立。第 19 条讲的是和警察、医生、柜员打交道时该有的预期，引的是法规，不是实验，所以等级记 C。第 15 条（把悲观念头当症状看）和第 22 条（把「别人要求我完美」当症状看）引的是死亡率与自杀风险的数字，口径和本节其他条目不一样，不放在一起比较。', 25, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(4, 4, '不要浪费时间', 4, '本节只算时间账。看的是每天、每周、每年能省回多少小时，或者一件事按时做完的比例能提高多少。这里不把时间换算成寿命，也不换算成钱。涉及钱的地方只给算法，不给结论。本节多数条目的证据是单独一项研究，或者是时间利用调查的总量统计，所以等级以 B、C 为主。', '本节只算时间账。看的是每天、每周、每年能省回多少小时，或者一件事按时做完的比例能提高多少。这里不把时间换算成寿命，也不换算成钱。涉及钱的地方只给算法，不给结论。本节多数条目的证据是单独一项研究，或者是时间利用调查的总量统计，所以等级以 B、C 为主。', 18, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(5, 5, '不要浪费钱', 5, '这一节只算钱：能省下多少，每年收益差多少，一笔钱长期平均下来能拿回多少。这些不换算成寿命或时间。涉及投资的条目只讲怎么算账，只用核实过的历史数据，都不构成投资建议。', '这一节只算钱：能省下多少，每年收益差多少，一笔钱长期平均下来能拿回多少。这些不换算成寿命或时间。涉及投资的条目只讲怎么算账，只用核实过的历史数据，都不构成投资建议。', 46, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(6, 6, '反面清单', 6, '本节收的是「看起来便宜又有效」的东西。翻开原始研究之后，它们的好处接近零、等于零，有的还是负的。排的顺序看两件事：大家在这上面花的钱多不多，支持它的证据硬不硬。越靠前的越值得先停掉。', '本节收的是「看起来便宜又有效」的东西。翻开原始研究之后，它们的好处接近零、等于零，有的还是负的。排的顺序看两件事：大家在这上面花的钱多不多，支持它的证据硬不硬。越靠前的越值得先停掉。', 30, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(7, 7, '没钱的时候怎么活', 7, '这一节算的是钱和保障。能领多少钱、能免多少钱、能得到什么服务、要满足什么条件，都写在里面，不折算成寿命。政策每年都在变，各地也不一样，所以金额和门槛都以你所在地当年公布的为准。条目的排序是：不花钱、手续少、见效快的排在前面。要攒长期资格的、各地差别大的排在后面。只凭经验、没有官方文件的放在最后。', '这一节算的是钱和保障。能领多少钱、能免多少钱、能得到什么服务、要满足什么条件，都写在里面，不折算成寿命。政策每年都在变，各地也不一样，所以金额和门槛都以你所在地当年公布的为准。条目的排序是：不花钱、手续少、见效快的排在前面。要攒长期资格的、各地差别大的排在后面。只凭经验、没有官方文件的放在最后。', 22, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(8, 8, '别把自己搭进去：法律与财产安全', 8, '这一节算钱和人身自由，不换算成寿命。讲的是三件事：法律规定你要担什么责任、照着做能少赔多少钱、出了事你在程序上有哪些权利。条款号都和官方原文核对过。排序的办法是：一次出事损失最大、做起来又最省事的放最前面；需要提前安排的放中间；只有经验、没有官方文件撑着的放最后。', '这一节算钱和人身自由，不换算成寿命。讲的是三件事：法律规定你要担什么责任、照着做能少赔多少钱、出了事你在程序上有哪些权利。条款号都和官方原文核对过。排序的办法是：一次出事损失最大、做起来又最省事的放最前面；需要提前安排的放中间；只有经验、没有官方文件撑着的放最后。', 46, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(9, 9, '普通人容易踩的法律红线', 9, '这一节算两笔账：你的人身自由，和你的钱。下面这些事，普通人常以为「没什么」，实际会被拘留、罚款，重的还会判刑。每条都给出法条里的具体数字，以及官方渠道公布过的案例。本节引的治安管理处罚法是 2025 年修订版，2026 年 1 月 1 日起施行，条款号和旧法不一样。刑法引的是北京市公安交管局转载的「根据刑法修正案（十一）修正」的整合文本，正文里会注明对应的修正案。条目的顺序，按「最容易不小心踩到」加「后果最重」从高到低排。', '这一节算两笔账：你的人身自由，和你的钱。下面这些事，普通人常以为「没什么」，实际会被拘留、罚款，重的还会判刑。每条都给出法条里的具体数字，以及官方渠道公布过的案例。本节引的治安管理处罚法是 2025 年修订版，2026 年 1 月 1 日起施行，条款号和旧法不一样。刑法引的是北京市公安交管局转载的「根据刑法修正案（十一）修正」的整合文本，正文里会注明对应的修正案。条目的顺序，按「最容易不小心踩到」加「后果最重」从高到低排。', 26, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(10, 10, '恋爱和结婚划不划算', 10, '本节把「结婚划不划算」拆成钱、时间、健康、法律风险和关系质量几笔账，分开算。每笔账只用能查到出处的数字，出处限于官方统计，或者荟萃分析（把多项研究的数据汇总起来重算一遍）。这里不做道德判断，也不替你下结论。健康那几笔按死亡风险算，时间那几笔按每天多少分钟算，法律那几笔按法条怎么写算。这三种算法之间不互相换算。拆账方法、填空清单和常见误区见 docs/结婚划不划算.md。', '本节把「结婚划不划算」拆成钱、时间、健康、法律风险和关系质量几笔账，分开算。每笔账只用能查到出处的数字，出处限于官方统计，或者荟萃分析（把多项研究的数据汇总起来重算一遍）。这里不做道德判断，也不替你下结论。健康那几笔按死亡风险算，时间那几笔按每天多少分钟算，法律那几笔按法条怎么写算。这三种算法之间不互相换算。拆账方法、填空清单和常见误区见 docs/结婚划不划算.md。', 20, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(11, 11, '程序员和技术人容易踩的红线', 11, '本节口径是人身自由与金钱，换回的是「别被关」和「别赔钱」。写代码、做技术的人，常把下面这些事当成「只是技术问题」，可它们对应的是刑法里的具体罪名，或者民事上要赔的具体一笔钱。每条都给出法条里的数字，以及最高人民检察院、最高人民法院官网公布的案例。刑法引用的是北京市公安交管局转载的「根据刑法修正案（十一）修正」整合文本。条目顺序按「技术人最容易以为没事 × 后果最重」从高到低排。第 1 条是通用的一条，讲动手前怎么判断，以及出事之后先做什么。', '本节口径是人身自由与金钱，换回的是「别被关」和「别赔钱」。写代码、做技术的人，常把下面这些事当成「只是技术问题」，可它们对应的是刑法里的具体罪名，或者民事上要赔的具体一笔钱。每条都给出法条里的数字，以及最高人民检察院、最高人民法院官网公布的案例。刑法引用的是北京市公安交管局转载的「根据刑法修正案（十一）修正」整合文本。条目顺序按「技术人最容易以为没事 × 后果最重」从高到低排。第 1 条是通用的一条，讲动手前怎么判断，以及出事之后先做什么。', 19, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(12, 12, '创业与做生意：别把家底赔进去', 12, '这一节只算钱和法律责任，不折算成寿命。开一家店、办一家公司，哪一步会把你自己的钱、家里的钱、配偶的钱一起赔进去？法律怎么规定，能不能提前隔开？最容易把家底赔进去、又最省事就能避开的条目，放在最前面。所以签字类的条目靠前，要自己动手做的方法靠后。只凭经验写、没有文献支撑的，标 C 级。', '这一节只算钱和法律责任，不折算成寿命。开一家店、办一家公司，哪一步会把你自己的钱、家里的钱、配偶的钱一起赔进去？法律怎么规定，能不能提前隔开？最容易把家底赔进去、又最省事就能避开的条目，放在最前面。所以签字类的条目靠前，要自己动手做的方法靠后。只凭经验写、没有文献支撑的，标 C 级。', 24, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(13, 13, '紧急情况：先做什么', 13, '本节讲出了事先做什么、再做什么、什么不要做。急救和野外的条目算的是特定死因和活下来的比例。威胁和骗局的条目算的是钱和人身自由。两类数字不互相换算。条目的顺序按「这事多常见 × 做对做错差多少条命」从高到低排。这些条目首先是给你自己和配偶、直系亲属用的。心脏骤停有 79.2% 发生在家里，你最可能救的就是家里人。对朋友同事次之。对陌生人也不是一点好处没有，但这一档最低，还可能被讹、被卷进案子。所以这类条目把保护自己的动作和免责的条款写在前面。 本节只收几分钟内要做的动作。认出骗局、被人拿把柄要钱，处置要按天算，不在这一节。反诈的硬规则和七种高发骗局见第 8 节第 3 条（反诈硬规则）。被人拿隐私照片、裸聊录像要钱见第 8 节第 32 条（对方拿把柄来要钱）。钱已经转出去了，立刻打 110 或 96110 要求止付，见第 8 节第 2 条（止付）。', '本节讲出了事先做什么、再做什么、什么不要做。急救和野外的条目算的是特定死因和活下来的比例。威胁和骗局的条目算的是钱和人身自由。两类数字不互相换算。条目的顺序按「这事多常见 × 做对做错差多少条命」从高到低排。这些条目首先是给你自己和配偶、直系亲属用的。心脏骤停有 79.2% 发生在家里，你最可能救的就是家里人。对朋友同事次之。对陌生人也不是一点好处没有，但这一档最低，还可能被讹、被卷进案子。所以这类条目把保护自己的动作和免责的条款写在前面。 本节只收几分钟内要做的动作。认出骗局、被人拿把柄要钱，处置要按天算，不在这一节。反诈的硬规则和七种高发骗局见第 8 节第 3 条（反诈硬规则）。被人拿隐私照片、裸聊录像要钱见第 8 节第 32 条（对方拿把柄来要钱）。钱已经转出去了，立刻打 110 或 96110 要求止付，见第 8 节第 2 条（止付）。', 44, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(14, 14, '账号与信息安全', 14, '口径：金钱与个人信息。账号被别人登进去，丢的先是钱。对方还会用你的账号去骗你通讯录里的人。你的身份也等于被人拿走了。', '口径：金钱与个人信息。账号被别人登进去，丢的先是钱。对方还会用你的账号去骗你通讯录里的人。你的身份也等于被人拿走了。', 10, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(15, 15, '租房与买房', 15, '口径：金钱。租房最容易亏钱的地方是押金和中介。买房最费钱的地方是贷款利息，还有卖方知道、你不知道的那些事。', '口径：金钱。租房最容易亏钱的地方是押金和中介。买房最费钱的地方是贷款利息，还有卖方知道、你不知道的那些事。', 9, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(16, 16, '得了慢性病之后怎么活', 16, '口径：总死亡率与金钱。查出慢性病以后往往还有几十年要过，本节算的是这几十年怎么管。', '口径：总死亡率与金钱。查出慢性病以后往往还有几十年要过，本节算的是这几十年怎么管。', 9, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(17, 17, '家里有老人', 17, '口径：金钱与人身自由。家里有老人，多数麻烦不是钱不够，是没提前把话说清楚、把字签好。最后两条讲长期卧床的压疮和白内障手术，按死亡率算账，不和本节其他条目比较。', '口径：金钱与人身自由。家里有老人，多数麻烦不是钱不够，是没提前把话说清楚、把字签好。最后两条讲长期卧床的压疮和白内障手术，按死亡率算账，不和本节其他条目比较。', 9, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(18, 18, '养孩子划不划算', 18, '这一节算的是钱和时间两笔账。和第 10 节算结婚账一样，这里只把账拆开给你看，不替你下结论。已经怀孕、要照流程一步步办事的，看第 27 节。', '这一节算的是钱和时间两笔账。和第 10 节算结婚账一样，这里只把账拆开给你看，不替你下结论。已经怀孕、要照流程一步步办事的，看第 27 节。', 6, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(19, 19, '在职、离职和工伤', 19, '这一节算的是钱：钱怎么算、字怎么签、期限怎么算。前三条讲你还在岗时就该拿到手的钱，中间六条讲离职，接着七条讲职业病和工伤。工伤的钱比被裁大一个量级，期限也更硬。职业病造成的损伤换不回来。节末还有四条：在单位被欺负怎么办、离职证明怎么要、离职补偿的个税怎么算、换城市工作时社保关系怎么转过去。', '这一节算的是钱：钱怎么算、字怎么签、期限怎么算。前三条讲你还在岗时就该拿到手的钱，中间六条讲离职，接着七条讲职业病和工伤。工伤的钱比被裁大一个量级，期限也更硬。职业病造成的损伤换不回来。节末还有四条：在单位被欺负怎么办、离职证明怎么要、离职补偿的个税怎么算、换城市工作时社保关系怎么转过去。', 19, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(20, 20, '刚出生的孩子怎么带', 20, '口径：婴儿死亡率与金钱。这一节只收关系到孩子能不能活下来、或者你要花多少钱的事，而且只收差别足够大、又有硬证据的。怎么哄、怎么带这些育儿细节，本书不写。出生之前和出院当天要办的事，见第 27 节。', '口径：婴儿死亡率与金钱。这一节只收关系到孩子能不能活下来、或者你要花多少钱的事，而且只收差别足够大、又有硬证据的。怎么哄、怎么带这些育儿细节，本书不写。出生之前和出院当天要办的事，见第 27 节。', 14, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(21, 21, '出国、旅行与境外安全', 21, '这一节算的是钱和人身自由，有几条还关系到人身安全。到了国外，管你的是所在国的法律，不是中国的。中国使领馆能帮你到哪一步，有明确的界线。', '这一节算的是钱和人身自由，有几条还关系到人身安全。到了国外，管你的是所在国的法律，不是中国的。中国使领馆能帮你到哪一步，有明确的界线。', 11, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(22, 22, '怎么放松：娱乐场所和减压', 22, '前半节讲娱乐场所里哪些钱花得冤、安全出口在哪，口径是金钱和人身自由。后半节讲怎么减压，口径是精力和总死亡率。两半的数字不放在一起换算。第 3 节已经写过情绪低落时先做哪几件事，这里给更具体的做法。', '前半节讲娱乐场所里哪些钱花得冤、安全出口在哪，口径是金钱和人身自由。后半节讲怎么减压，口径是精力和总死亡率。两半的数字不放在一起换算。第 3 节已经写过情绪低落时先做哪几件事，这里给更具体的做法。', 10, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(23, 23, '学什么技能划算', 23, '这一节算的是钱和时间，第 2 条另外算死亡率。前六条回答一个问题：还要不要接着读书。第 1 条先说法律划掉了哪一段选项，第 2 条算读书和寿命的关系，第 3 条看全国人的学历都在哪一档。第 4 条讲读不起的时候有哪些资助，第 5 条讲没考上普高还有什么路，第 6 条把「读书还是打工」算成一道题，给一个自己动手算的方法。后七条回答另一个问题：决定学点东西之后怎么挑。中国按工种分的工资统计，从公开的官方渠道很难逐项核实。所以这里只写查得到出处的几件事：多读一年书工资大概多多少（也叫教育回报率）、证书合不合法怎么验、培训补贴从哪里来、挑技能时看哪个维度更不容易被顶掉。具体某个工种一个月挣多少，本书不给数字。第 14 到 19 条回答第三个问题：定下来学什么之后，怎么学才省时间。这六条算的是时间，不和钱做换算。第 20 到 23 条回答第四个问题：已经在做专业技术工作了，职称从哪里报、怎么考、别踩什么坑、评上值多少。', '这一节算的是钱和时间，第 2 条另外算死亡率。前六条回答一个问题：还要不要接着读书。第 1 条先说法律划掉了哪一段选项，第 2 条算读书和寿命的关系，第 3 条看全国人的学历都在哪一档。第 4 条讲读不起的时候有哪些资助，第 5 条讲没考上普高还有什么路，第 6 条把「读书还是打工」算成一道题，给一个自己动手算的方法。后七条回答另一个问题：决定学点东西之后怎么挑。中国按工种分的工资统计，从公开的官方渠道很难逐项核实。所以这里只写查得到出处的几件事：多读一年书工资大概多多少（也叫教育回报率）、证书合不合法怎么验、培训补贴从哪里来、挑技能时看哪个维度更不容易被顶掉。具体某个工种一个月挣多少，本书不给数字。第 14 到 19 条回答第三个问题：定下来学什么之后，怎么学才省时间。这六条算的是时间，不和钱做换算。第 20 到 23 条回答第四个问题：已经在做专业技术工作了，职称从哪里报、怎么考、别踩什么坑、评上值多少。', 23, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(24, 24, '看病：怎么少花钱少走弯路', 24, '口径：金钱与时间。这一节讲看病本身怎么走：先去哪家医院，怎么往上转，钱能少花在哪。另外讲急诊怎么排队，重伤治完之后要做哪些鉴定、办哪些证。能领什么待遇见第 7 节。慢性病长期怎么管见第 16 节。急症现场先做什么见第 13 节。 本节主要依据国务院办公厅 2026 年 4 月印发的《关于加快建设分级诊疗体系的若干措施》。分级诊疗就是按病情轻重决定先去哪一级医院。这份文件把「去基层」和「省钱」直接挂上了钩。但各地落地进度不同，正文写的是国家层面的规则。具体到你所在的统筹地区，要以当地医保和卫健部门的说法为准。统筹地区就是你的医保参保地，通常是一个市。', '口径：金钱与时间。这一节讲看病本身怎么走：先去哪家医院，怎么往上转，钱能少花在哪。另外讲急诊怎么排队，重伤治完之后要做哪些鉴定、办哪些证。能领什么待遇见第 7 节。慢性病长期怎么管见第 16 节。急症现场先做什么见第 13 节。 本节主要依据国务院办公厅 2026 年 4 月印发的《关于加快建设分级诊疗体系的若干措施》。分级诊疗就是按病情轻重决定先去哪一级医院。这份文件把「去基层」和「省钱」直接挂上了钩。但各地落地进度不同，正文写的是国家层面的规则。具体到你所在的统筹地区，要以当地医保和卫健部门的说法为准。统筹地区就是你的医保参保地，通常是一个市。', 12, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(25, 25, '人走了以后要办什么', 25, '口径：金钱。本节只讲手续怎么办、钱怎么拿，包括人刚走时先做什么、哪些费用有清单可以对。还有哪些账户里的钱能取回来，哪些事近亲属有权出面办。前五条按事情发生的先后排，依次是现场、死亡证明、遗体和火化、对死因有异议怎么办、销户。后面几条按性价比排。老人生前该做的安排，比如意定监护、遗嘱、账户，见第 17 节。因工死亡的三笔待遇见第 19 节。 殡葬这部分依据新版《殡葬管理条例》，2026 年 3 月 30 日起施行。养老保险的丧葬补助金和遗属抚恤金给多少，由人力资源社会保障部门另外规定。这次没拿到能逐字核对的原文，所以正文不写具体金额。', '口径：金钱。本节只讲手续怎么办、钱怎么拿，包括人刚走时先做什么、哪些费用有清单可以对。还有哪些账户里的钱能取回来，哪些事近亲属有权出面办。前五条按事情发生的先后排，依次是现场、死亡证明、遗体和火化、对死因有异议怎么办、销户。后面几条按性价比排。老人生前该做的安排，比如意定监护、遗嘱、账户，见第 17 节。因工死亡的三笔待遇见第 19 节。 殡葬这部分依据新版《殡葬管理条例》，2026 年 3 月 30 日起施行。养老保险的丧葬补助金和遗属抚恤金给多少，由人力资源社会保障部门另外规定。这次没拿到能逐字核对的原文，所以正文不写具体金额。', 10, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(26, 26, '做一个网站或平台：资质、备案和服务器', 26, '你想做一个网站或者 App。本节回答四件事：它在法律上算哪种生意，要办哪张证，服务器放在哪里，用户在上面发的东西和收的钱谁来负责。口径是人身自由与金钱。条目的顺序是：先写会坐牢的，再写要先办证的，然后是平台每天都要做的事，最后一条是选服务器的经验，那条只能给判断、给不出数字。你是受雇的技术人员，红线见第 11 节。公司怎么注册、怎么报税，见第 12 节，本节不重复。各类证的对照表和选服务器的决策表，见 docs/做平台要办哪些证.md。', '你想做一个网站或者 App。本节回答四件事：它在法律上算哪种生意，要办哪张证，服务器放在哪里，用户在上面发的东西和收的钱谁来负责。口径是人身自由与金钱。条目的顺序是：先写会坐牢的，再写要先办证的，然后是平台每天都要做的事，最后一条是选服务器的经验，那条只能给判断、给不出数字。你是受雇的技术人员，红线见第 11 节。公司怎么注册、怎么报税，见第 12 节，本节不重复。各类证的对照表和选服务器的决策表，见 docs/做平台要办哪些证.md。', 11, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(27, 27, '怀孕和生产：从发现怀孕到出院办证', 27, '这一节前半段算的是孕妇和胎儿的死亡风险。后半段算的是钱和跑腿时间。两种账不放在一起换算。内容只讲「什么时候做什么」。孕期营养、胎教这类没有硬证据、或者作用很小的事，这里不写。生育津贴、产假和养孩子的钱账见第 18 节，孩子出生之后怎么带见第 20 节，急症见第 13 节。 世界卫生组织给的数字：2023 年，全球约有 26 万名女性死于怀孕和生产。其中约 75% 死于这五类原因：产后大出血、感染、妊娠期高血压疾病（怀孕后血压升高的一类病，包括子痫前期和子痫）、分娩时的并发症、不安全的人工流产。世界卫生组织同时说，「大多数孕产妇死亡是可以预防的，因为预防和处理并发症的医疗手段都是已知的」。这一节里作用最大的几条，就是把这几类问题提前拦下来。', '这一节前半段算的是孕妇和胎儿的死亡风险。后半段算的是钱和跑腿时间。两种账不放在一起换算。内容只讲「什么时候做什么」。孕期营养、胎教这类没有硬证据、或者作用很小的事，这里不写。生育津贴、产假和养孩子的钱账见第 18 节，孩子出生之后怎么带见第 20 节，急症见第 13 节。 世界卫生组织给的数字：2023 年，全球约有 26 万名女性死于怀孕和生产。其中约 75% 死于这五类原因：产后大出血、感染、妊娠期高血压疾病（怀孕后血压升高的一类病，包括子痫前期和子痫）、分娩时的并发症、不安全的人工流产。世界卫生组织同时说，「大多数孕产妇死亡是可以预防的，因为预防和处理并发症的医疗手段都是已知的」。这一节里作用最大的几条，就是把这几类问题提前拦下来。', 16, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(28, 28, '别为了外形把身体搞坏', 28, '本节说的是「为了改变外形而对身体动手」的几种做法：饿肚子、吃药、打针、开刀。这几件事，决定多半是和别人比较之后做的，代价却全落在自己身上，而且相当一部分改不回来。 本节不评价任何人想把自己变成什么样子，那是各人自己的事。同一个目标，可以找「有处方、有资质、有复查」的，也可以「网购、美容院、自己加量」，本节只比这两种做法的风险差多少。算账主要看身体上实际出了什么事，比如失明、住院、死亡。医美那两条还涉及非法行医的刑事责任。', '本节说的是「为了改变外形而对身体动手」的几种做法：饿肚子、吃药、打针、开刀。这几件事，决定多半是和别人比较之后做的，代价却全落在自己身上，而且相当一部分改不回来。 本节不评价任何人想把自己变成什么样子，那是各人自己的事。同一个目标，可以找「有处方、有资质、有复查」的，也可以「网购、美容院、自己加量」，本节只比这两种做法的风险差多少。算账主要看身体上实际出了什么事，比如失明、住院、死亡。医美那两条还涉及非法行医的刑事责任。', 9, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(29, 29, '遭遇重大打击之后', 29, '亲人去世、被告知重病、失业、离婚。这几件事在研究里有个共同点：出事的不只是心情，还有身体。风险最高的那一段，集中在头几周到头一年。这一节不讲怎么「走出来」，只讲这段时间里哪些事必须有人盯住，哪些决定必须往后放，什么时候该去挂号。多数条目算的是死亡概率。谈花钱和待遇的四条算的是钱：别一上来就花钱做哀伤咨询（第 9 条）、打 12356 和挂心理门诊（第 11 条）、不可逆的大决定往后推（第 12 条）、别拿死当还债的办法（第 13 条）。两类数字不互相换算。没有亲人也没有朋友可找的，「找个人盯住」这句话怎么落地见第 6 条。 亲人去世当时的手续、遗体和该取的钱见第 25 节。老人生前的监护与遗嘱见第 17 节。失业能领什么见第 7 节。情绪低落时的运动与光照见第 3 节和第 22 节。有自杀念头时先打 12356 见第 1 节第 25 条、念头的时间尺度见第 1 节第 32 条、救回来之后的后遗症见第 1 节第 33 条。这些本节都不重复。', '亲人去世、被告知重病、失业、离婚。这几件事在研究里有个共同点：出事的不只是心情，还有身体。风险最高的那一段，集中在头几周到头一年。这一节不讲怎么「走出来」，只讲这段时间里哪些事必须有人盯住，哪些决定必须往后放，什么时候该去挂号。多数条目算的是死亡概率。谈花钱和待遇的四条算的是钱：别一上来就花钱做哀伤咨询（第 9 条）、打 12356 和挂心理门诊（第 11 条）、不可逆的大决定往后推（第 12 条）、别拿死当还债的办法（第 13 条）。两类数字不互相换算。没有亲人也没有朋友可找的，「找个人盯住」这句话怎么落地见第 6 条。 亲人去世当时的手续、遗体和该取的钱见第 25 节。老人生前的监护与遗嘱见第 17 节。失业能领什么见第 7 节。情绪低落时的运动与光照见第 3 节和第 22 节。有自杀念头时先打 12356 见第 1 节第 25 条、念头的时间尺度见第 1 节第 32 条、救回来之后的后遗症见第 1 节第 33 条。这些本节都不重复。', 13, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(30, 30, '上学以后的孩子', 30, '第 20 节讲的是孩子刚出生那一年。第 18 节算的是养孩子要花多少钱、多少时间。中间 3 到 18 岁这十几年，写在这一节。分龄管屏幕那一条从 0 岁写起，因为官方的分档就是 0～3 岁、3～6 岁、中小学三档，拆开写反而不好用。本节回答的是：「别耽误学习」和「身体」撞在一起的时候，哪些事不能等。这些事有时间窗口，过了就补不回来。学业该不该那么卷，本节不讨论，只给窗口和数字。 前八条、第 12 条（散瞳验光）、第 13 条（窝沟封闭）和第 15 到 18 条，算的是死亡和身体、心理上真落下的损害。其中第 16、17 条讲家里怎么管孩子：不打不骂，去上教具体做法的家长课。第 18 条讲别把孩子送进封闭管理的戒网瘾学校。第 9 条（不买「治愈近视」的产品）算钱。第 10 条（睡眠作业体育排名的明文规定）、第 11 条（休学保留学籍）和第 14 条（孩子爱打游戏）算时间。溺水、交通、头盔、HPV 疫苗见第 1 节。婴幼儿见第 20 节。孩子被骗和游戏充值见第 5 节。未成年人自己别踩的红线见第 9 节。急症怎么认、怎么叫车见第 13 节。家长去世后的孩子见第 29 节。这些都不在本节重复。', '第 20 节讲的是孩子刚出生那一年。第 18 节算的是养孩子要花多少钱、多少时间。中间 3 到 18 岁这十几年，写在这一节。分龄管屏幕那一条从 0 岁写起，因为官方的分档就是 0～3 岁、3～6 岁、中小学三档，拆开写反而不好用。本节回答的是：「别耽误学习」和「身体」撞在一起的时候，哪些事不能等。这些事有时间窗口，过了就补不回来。学业该不该那么卷，本节不讨论，只给窗口和数字。 前八条、第 12 条（散瞳验光）、第 13 条（窝沟封闭）和第 15 到 18 条，算的是死亡和身体、心理上真落下的损害。其中第 16、17 条讲家里怎么管孩子：不打不骂，去上教具体做法的家长课。第 18 条讲别把孩子送进封闭管理的戒网瘾学校。第 9 条（不买「治愈近视」的产品）算钱。第 10 条（睡眠作业体育排名的明文规定）、第 11 条（休学保留学籍）和第 14 条（孩子爱打游戏）算时间。溺水、交通、头盔、HPV 疫苗见第 1 节。婴幼儿见第 20 节。孩子被骗和游戏充值见第 5 节。未成年人自己别踩的红线见第 9 节。急症怎么认、怎么叫车见第 13 节。家长去世后的孩子见第 29 节。这些都不在本节重复。', 18, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(31, 31, '十八岁之后有哪几条路', 31, '这一节算的是钱和时间，拒服兵役那一条还关系到人身自由。这是一张路径地图，不是某一条路的说明书。本节先把各条路的法定门槛摆在一起，再逐条写那些知道了才用得上的东西：当兵能拿到什么，进体制内除了考公还有哪些口子，高考填志愿时哪两个专业直接对着编制，学历后来还能不能补，想出国打工该找什么样的公司，不进单位的人社保怎么办，没本钱起步有没有国家替你出一部分利息的钱可借。 十八岁之后能走的路，远不止这一节写到的这些。这里只收有全国层面的公开文件、门槛和待遇能逐条核对的那几条。进国企、进工厂、当船员、做自由职业、接着读高中读大学，这些路也能走。只是它们没有统一文件可查，本书不凭印象替它们写条件。 选哪条路是你自己的事。本节只提供两样东西：门槛写在哪份文件里，走上去之后有哪些期限和资格过期就作废。读书还是打工那道题怎么算、技能怎么挑，见第 23 节。进了单位之后的加班费、工伤和离职补偿，见第 19 节。开店办公司的本钱和退场，见第 12 节。出国留学见第 32 节。失业之后的保障见第 7 节。这些都不重复。', '这一节算的是钱和时间，拒服兵役那一条还关系到人身自由。这是一张路径地图，不是某一条路的说明书。本节先把各条路的法定门槛摆在一起，再逐条写那些知道了才用得上的东西：当兵能拿到什么，进体制内除了考公还有哪些口子，高考填志愿时哪两个专业直接对着编制，学历后来还能不能补，想出国打工该找什么样的公司，不进单位的人社保怎么办，没本钱起步有没有国家替你出一部分利息的钱可借。 十八岁之后能走的路，远不止这一节写到的这些。这里只收有全国层面的公开文件、门槛和待遇能逐条核对的那几条。进国企、进工厂、当船员、做自由职业、接着读高中读大学，这些路也能走。只是它们没有统一文件可查，本书不凭印象替它们写条件。 选哪条路是你自己的事。本节只提供两样东西：门槛写在哪份文件里，走上去之后有哪些期限和资格过期就作废。读书还是打工那道题怎么算、技能怎么挑，见第 23 节。进了单位之后的加班费、工伤和离职补偿，见第 19 节。开店办公司的本钱和退场，见第 12 节。出国留学见第 32 节。失业之后的保障见第 7 节。这些都不重复。', 16, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(32, 32, '出国留学：身份、打工、保险和回国认证', 32, '本节算钱和人身自由两笔账，不讨论该不该出国，也不比较学校好坏。下面四件事不知道就要吃亏：签证身份怎么才算没断、打工时数的上限在哪、哪几笔保险和费用是必须交的、回国以后这张文凭能不能被认。 覆盖美国、加拿大、英国、澳大利亚四个国家，数字一国一国列。来源是各国移民局和中国教育部的官方网页。各国的留学政策改得很勤，比中国的法规还勤。本节所有数字的截至日期是 2026 年 9 月。出发前和每次续签前，都照来源栏的链接自己再查一遍。 人在境外出了事怎么找使领馆、12308 能管什么、境外医疗和转运保险怎么买，见第 21 节。读书还是打工那道账，见第 23 节。账号被盗见第 14 节，电信诈骗见第 8 节。这些都不重复写。', '本节算钱和人身自由两笔账，不讨论该不该出国，也不比较学校好坏。下面四件事不知道就要吃亏：签证身份怎么才算没断、打工时数的上限在哪、哪几笔保险和费用是必须交的、回国以后这张文凭能不能被认。 覆盖美国、加拿大、英国、澳大利亚四个国家，数字一国一国列。来源是各国移民局和中国教育部的官方网页。各国的留学政策改得很勤，比中国的法规还勤。本节所有数字的截至日期是 2026 年 9 月。出发前和每次续签前，都照来源栏的链接自己再查一遍。 人在境外出了事怎么找使领馆、12308 能管什么、境外医疗和转运保险怎么买，见第 21 节。读书还是打工那道账，见第 23 节。账号被盗见第 14 节，电信诈骗见第 8 节。这些都不重复写。', 10, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(33, 33, '残疾之后怎么活', 33, '这一节写的是残疾已经发生之后的日子。怎么防住致残，在第 1 节和第 13 节，这里不重复。 四种口径分开算，不互相换算。急症和并发症那几条按死亡率算。补贴、待遇、打官司那几条按金钱算。上学、办事那几条按时间算。精神障碍住院、行为能力和监护那几条按人身自由算。 世界卫生组织的说明书给了三个数字。全球约有 13 亿人存在显著功能障碍，占世界人口的 16%，大约每六个人里有一个。部分残疾人比没有残疾的人早死最多 20 年。残疾人得抑郁、哮喘、糖尿病、卒中、肥胖或者口腔健康不良的风险是两倍。这些差距里，很大一部分不是残疾本身造成的，是看不上病、上不了学、找不到工作、出不了门造成的。所以这一节的条目，一半是身体，一半是手续和权利。 已经写在别处的五件事，这里只指路，不重复。残疾人证怎么办、七个类别和一到四级怎么评，见第 24 节第 10 条（残疾人证）。伤残鉴定要等到什么时候做，见第 24 节第 9 条（伤残鉴定）。残疾人两项补贴怎么领，见第 7 节第 8 条（两项补贴）。工伤的劳动能力鉴定和伤残等级换算成多少钱，见第 19 节第 14 条（劳动能力鉴定）。重度失能的长期护理保险怎么申请，见第 17 节第 7 条（长期护理保险）。那一条写在「家里有老人」那节，但这项待遇没有年龄门槛，年轻人一样能领。 本节大部分条目的受益人是你自己和家人，属于最高的两档。涉及别人的地方在备注里单独写。', '这一节写的是残疾已经发生之后的日子。怎么防住致残，在第 1 节和第 13 节，这里不重复。 四种口径分开算，不互相换算。急症和并发症那几条按死亡率算。补贴、待遇、打官司那几条按金钱算。上学、办事那几条按时间算。精神障碍住院、行为能力和监护那几条按人身自由算。 世界卫生组织的说明书给了三个数字。全球约有 13 亿人存在显著功能障碍，占世界人口的 16%，大约每六个人里有一个。部分残疾人比没有残疾的人早死最多 20 年。残疾人得抑郁、哮喘、糖尿病、卒中、肥胖或者口腔健康不良的风险是两倍。这些差距里，很大一部分不是残疾本身造成的，是看不上病、上不了学、找不到工作、出不了门造成的。所以这一节的条目，一半是身体，一半是手续和权利。 已经写在别处的五件事，这里只指路，不重复。残疾人证怎么办、七个类别和一到四级怎么评，见第 24 节第 10 条（残疾人证）。伤残鉴定要等到什么时候做，见第 24 节第 9 条（伤残鉴定）。残疾人两项补贴怎么领，见第 7 节第 8 条（两项补贴）。工伤的劳动能力鉴定和伤残等级换算成多少钱，见第 19 节第 14 条（劳动能力鉴定）。重度失能的长期护理保险怎么申请，见第 17 节第 7 条（长期护理保险）。那一条写在「家里有老人」那节，但这项待遇没有年龄门槛，年轻人一样能领。 本节大部分条目的受益人是你自己和家人，属于最高的两档。涉及别人的地方在备注里单独写。', 20, 'admin', 1);
INSERT INTO `qh_chapter` (`id`, `num`, `title`, `cover`, `summary`, `content`, `item_count`, `creator`, `tenant_id`) VALUES
(34, 34, '家里的常备药别吃出事', 34, '退烧药、止痛药、感冒药、胃药、止泻药，很多在药店就能自己买。不用处方能买，不等于怎么吃都行。这一节不讲每种病该吃什么药，只挑一个动作就能避开重后果的几件事。 所有条目按死亡率口径算，包括肝衰竭、胃出血、新生儿肾衰竭这类健康终点。收益大多是「少出一次严重事故」，研究给不出「做了能少几成」的数字，收益量级是按后果轻重判断的，每条备注里写了凭什么定。 已经写在别处的，这里只指路。误服了药或清洁剂先做什么，见第 13 节第 20 条（误服）。慢性病的药按医嘱吃满，见第 16 节第 1 条（药按医嘱吃满）。网上买处方药要先过处方审核，见第 28 节第 6 条（减肥药就去医院拿处方）。 本节条目的受益人是你自己和家人，属于最高的两档。', '退烧药、止痛药、感冒药、胃药、止泻药，很多在药店就能自己买。不用处方能买，不等于怎么吃都行。这一节不讲每种病该吃什么药，只挑一个动作就能避开重后果的几件事。 所有条目按死亡率口径算，包括肝衰竭、胃出血、新生儿肾衰竭这类健康终点。收益大多是「少出一次严重事故」，研究给不出「做了能少几成」的数字，收益量级是按后果轻重判断的，每条备注里写了凭什么定。 已经写在别处的，这里只指路。误服了药或清洁剂先做什么，见第 13 节第 20 条（误服）。慢性病的药按医嘱吃满，见第 16 节第 1 条（药按医嘱吃满）。网上买处方药要先过处方审核，见第 28 节第 6 条（减肥药就去医院拿处方）。 本节条目的受益人是你自己和家人，属于最高的两档。', 11, 'admin', 1);
INSERT INTO `qh_chapter_item` (`chapter_id`, `sort_no`, `title`, `detail`, `level`, `creator`, `tenant_id`) VALUES
(1, 1, '骑车戴头盔', '头部重伤很难逆转，短途通勤也别省这一步。', 'A', 'admin', 1),
(1, 2, '走路时把手机收起来', '低头时对来车的判断会明显变慢，这是最常见的可避免伤害。', 'B', 'admin', 1),
(1, 3, '宿舍不碰大功率电器', '热得快、电煮锅、私拉插排是宿舍火灾的主要来源。', 'B', 'admin', 1),
(1, 4, '用明火时收起头发和衣袖', '实验室与宿舍的小火源，最先点着的就是头发和袖口。', 'C', 'admin', 1),
(1, 5, '按期接种该打的疫苗', '乙肝、HPV 这类疫苗防护明确，校医院多可预约，赶在暴露前完成。', 'A', 'admin', 1),
(1, 6, '持续的身体信号去查一次', '不明原因消瘦、持续低热、异常出血，别自己观察到期末。', 'B', 'admin', 1),
(2, 1, '先把烟戒掉', '在总死亡率上，戒烟是收益最大的单项动作之一。', 'A', 'admin', 1),
(2, 2, '血压血糖别觉得离自己远', '二十岁出头也可能偏高，体检异常一次就复查。', 'B', 'admin', 1),
(2, 3, '每周 150 分钟中等强度运动', '分散到五天也行，快走、骑车、打球都算。', 'A', 'admin', 1),
(2, 4, '别用「少量有益」替喝酒找理由', '目前的证据更支持喝得越少越好。', 'B', 'admin', 1),
(2, 5, '久坐每小时起身一次', '打断久坐本身就有独立收益，不必等攒够一小时运动。', 'B', 'admin', 1),
(2, 6, '把家族病史问清楚', '直系亲属早发的心血管或肿瘤病史，会改变你的筛查建议。', 'B', 'admin', 1),
(3, 1, '一次只做一件事', '同时开着课、聊天窗口和短视频，切换成本比你以为的高。', 'B', 'admin', 1),
(3, 2, '给手机设物理距离', '放进包里或另一个房间，比装专注软件更省意志力。', 'B', 'admin', 1),
(3, 3, '把日常决定提前做掉', '早饭吃什么、几点去操场，提前定好就不用每天重新消耗一次。', 'C', 'admin', 1),
